.piece{ .piece{position:relative;width:70%;height:70%;display:grid;place-items:center;border-radius:50%;font-size:clamp(14px,2.4vw,24px);line-height:1;letter-spacing:-1px;user-select:none;transform:translateZ(8px);isolation:isolate}

.piece.white{ .piece.white{color:#6d3546!important;background:radial-gradient(circle at 38% 28%,#fffef8 0 12%,#f7dbe1 28%,#d69ba8 68%,#9a5a68 100%)!important;border:2px solid #fff8f0!important;box-shadow:inset -5px -8px 12px rgba(91,43,57,.28),inset 4px 5px 8px rgba(255,255,255,.9),0 6px 9px rgba(62,34,42,.32),0 13px 18px rgba(62,34,42,.16);text-shadow:0 1px 0 rgba(255,255,255,.9)!important}

.piece.black{ .piece.black{color:#fff4ee!important;background:linear-gradient(145deg,#7a2f4d,#3d1d2b)!important;border-color:#d8a1ac!important;text-shadow:none!important}

.piece:before{ .piece:before{content:"";position:absolute;inset:9%;border-radius:50%;border:1px solid rgba(255,255,255,.34);pointer-events:none}

.piece:after{ .piece:after{content:"";position:absolute;width:54%;height:16%;left:23%;bottom:-9%;border-radius:50%;background:linear-gradient(90deg,rgba(55,34,39,.28),rgba(255,255,255,.12),rgba(55,34,39,.28));filter:blur(1px);z-index:-1}
sp.textContent=glyph[b[y][x]] 1
defeated.textContent=glyph[captureFx.piece] 1

