+.board{position:relative;overflow:hidden;border:9px solid #bc9670;border-radius:4px;transform:perspective(1400px) rotateX(1.8deg);box-shadow:0 24px 55px rgba(74,34,50,.28),0 8px 12px rgba(74,34,50,.18),inset 0 0 0 2px #ead9c4,inset 0 0 18px rgba(62,35,40,.22)}
+.board:after{content:"";position:absolute;inset:-9px;pointer-events:none;border:2px solid rgba(255,248,235,.85);box-shadow:inset 0 -8px 18px rgba(89,52,59,.2);z-index:20}
+.sq.light{background:linear-gradient(145deg,#faf4e8,#e1d2bd);box-shadow:inset 1px 1px 1px rgba(255,255,255,.8),inset -2px -2px 5px rgba(102,78,57,.08)}
+.sq.dark{background:linear-gradient(145deg,#ad5b70,#813247);box-shadow:inset 1px 1px 2px rgba(255,194,200,.18),inset -3px -4px 8px rgba(64,24,39,.28)}
+.sq:hover{z-index:2;filter:brightness(1.04);box-shadow:inset 0 0 0 3px rgba(255,245,225,.38)}
+.sq.selected{z-index:3;box-shadow:inset 0 0 0 5px #713d46,inset 0 0 14px rgba(255,236,190,.8)}
+.piece{width:78%;height:94%;transform:translateZ(18px) translateY(-2px);filter:drop-shadow(0 7px 3px rgba(48,22,32,.32));transition:transform .18s ease,filter .18s ease}.sq:hover .piece{transform:translateZ(22px) translateY(-5px) scale(1.025);filter:drop-shadow(0 10px 5px rgba(48,22,32,.36))}
+.piece svg{filter:drop-shadow(2px 3px 1px rgba(40,20,27,.25)) drop-shadow(-1px -1px 0 rgba(255,255,255,.22))}
+.side-panel{background:linear-gradient(145deg,rgba(255,255,255,.28),rgba(218,205,188,.12));box-shadow:inset 1px 0 0 rgba(255,255,255,.55)}
+.avatar{box-shadow:0 5px 10px rgba(74,34,50,.18),inset 2px 2px 5px rgba(255,255,255,.7),inset -3px -4px 6px rgba(112,75,83,.15)}
+.pill{box-shadow:0 3px 7px rgba(74,34,50,.12),inset 0 1px 0 rgba(255,255,255,.75);transition:transform .12s ease,box-shadow .12s ease}.pill:active{transform:translateY(2px);box-shadow:0 1px 3px rgba(74,34,50,.15),inset 0 2px 4px rgba(74,34,50,.12)}
 @keyframes piece-defeat{0%{opacity:1;transform:scale(1) rotate(0)}30%{opacity:1;transform:scale(1.16) rotate(-8deg)}100%{opacity:0;transform:scale(.12) rotate(35deg) translateY(-18px);filter:blur(2px)}}
 @keyframes impact-bloom{0%{opacity:0;transform:scale(.2)}25%{opacity:.9}100%{opacity:0;transform:scale(3.2)}}
 @media(prefers-reduced-motion:reduce){.defeated-piece,.impact-ring{animation-duration:.01ms}}
 </style></head>
